import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"ush — 完整 shell 参考","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/ush-reference.md","filePath":"zh/manual/ush-reference.md"}'),a={name:"zh/manual/ush-reference.md"};function r(s,t,n,l,i,h){return e(),o("div",null,[...t[0]||(t[0]=[c(`<h1 id="ush-—-完整-shell-参考" tabindex="-1">ush — 完整 shell 参考 <a class="header-anchor" href="#ush-—-完整-shell-参考" aria-label="Permalink to &quot;ush — 完整 shell 参考&quot;">​</a></h1><p><code>ush</code> 是 ring-3 shell 与默认启动项（内核的 <code>l1_launcher_boot_default()</code> 孵化它；它退出时 L0 停机）。它位于 <code>ocos/l1apps/ush/main.c</code> — 一个裸 ELF（唯一非 gzipped 的注册表 程序），输入用 SYS_READLINE(73)/SYS_GETCH(74)，程序用 fork+execve+wait4，管道用 SYS_PIPE(20)+SYS_DUP2(51)， 重定向用 SYS_OPEN/CLOSE。</p><h2 id="_12-个内建命令" tabindex="-1">12 个内建命令 <a class="header-anchor" href="#_12-个内建命令" aria-label="Permalink to &quot;12 个内建命令&quot;">​</a></h2><p>只有这十二个词由 shell 自身解释。其余一切都是注册表程序。</p><table tabindex="0"><thead><tr><th>内建</th><th>语法</th><th>行为</th></tr></thead><tbody><tr><td><code>cd</code></td><td><code>cd [dir]</code></td><td>切换 shell 的工作目录；无参数 = <code>/</code></td></tr><tr><td><code>help</code></td><td><code>help [-a|-w]</code></td><td>内建摘要 + 注册表计数行；<code>-a</code>/<code>--all</code> = 完整 A-Z 列表，<code>-w</code>/<code>--wp</code> = 按工作包分组（mega 组最先）</td></tr><tr><td><code>export</code></td><td><code>export VAR=val</code></td><td>设置环境变量（最多 32 个，名 ≤ 32，值 ≤ 128 字节）</td></tr><tr><td><code>alias</code></td><td><code>alias name=val</code> / <code>alias name value...</code></td><td>设置别名（最多 16 个，名 ≤ 32，值 ≤ 64）；裸 <code>alias</code> 列出全部；<code>alias name</code> 打印单个</td></tr><tr><td><code>unalias</code></td><td><code>unalias name</code></td><td>删除别名；无参数调用时打印 usage 错误</td></tr><tr><td><code>env</code></td><td><code>env</code></td><td>打印全部环境变量</td></tr><tr><td><code>set</code></td><td><code>set [VAR]</code></td><td>裸 <code>set</code> 显示变量；<code>set VAR</code> 打印 <code>VAR=value</code></td></tr><tr><td><code>history</code></td><td><code>history</code></td><td>带编号历史，1..n</td></tr><tr><td><code>jobs</code></td><td><code>jobs</code></td><td>列出后台作业表条目</td></tr><tr><td><code>fg</code></td><td><code>fg [job]</code></td><td><strong>不可用</strong> — 打印 <code>ush: job control requires external programs</code></td></tr><tr><td><code>bg</code></td><td><code>bg</code></td><td><strong>不可用</strong> — 相同消息</td></tr><tr><td><code>exit</code></td><td><code>exit</code></td><td><strong>被拒绝</strong> — <code>ush: &#39;exit&#39; is not available; use &#39;shutdown&#39; to power off, &#39;reboot&#39; to restart</code></td></tr></tbody></table><p>注：</p><ul><li><code>fg</code>/<code>bg</code> 是被识别的词，但作业<strong>恢复</strong>未实现。 <code>jobs</code> 列表与 <code>cmd &amp;</code> 后台启动是真实的（16 个作业槽； 父进程打印 <code>[n] &lt;pid&gt;</code>）。</li><li><code>exit</code> 被拒绝是因为无处可退 —— ush 就是启动项； 它的退出即会话结束（内核打印 <code>l1 launcher: default L1 app exited; L0 halting</code>）。</li><li>v2.x 中曾是内建的词（<code>ls</code>、<code>cat</code>、<code>wc</code>、 <code>grep</code>、<code>head</code>、<code>tail</code>、<code>mkdir</code>、<code>rmdir</code>、<code>touch</code>、<code>rm</code>、<code>cp</code>、<code>mv</code>、 <code>sort</code>、<code>uniq</code>、<code>ps</code>、<code>top</code>、<code>kill</code>、<code>date</code>、<code>uname</code>、<code>free</code>、<code>df</code>、 <code>stat</code>、<code>du</code>、<code>ln</code>、<code>chmod</code>、<code>chown</code>、<code>sed</code>、<code>awk</code>、<code>ping</code>、<code>wget</code>、 <code>netstat</code>、<code>ifconfig</code>、<code>nano</code>/<code>vi</code>/<code>edit</code>）现在是经 execve 到达的普通应用。</li></ul><h2 id="行编辑器" tabindex="-1">行编辑器 <a class="header-anchor" href="#行编辑器" aria-label="Permalink to &quot;行编辑器&quot;">​</a></h2><p>所有编辑都发生在原始 SYS_GETCH 码上；行长上限 511 字节。</p><table tabindex="0"><thead><tr><th>键</th><th>码</th><th>动作</th></tr></thead><tbody><tr><td>Up</td><td>0x80</td><td>上一条历史（草稿保留 — 见下文）</td></tr><tr><td>Down</td><td>0x81</td><td>下一条历史；越过最新条目后恢复你的草稿</td></tr><tr><td>Left / Right</td><td>0x82 / 0x83</td><td>按字形移动光标（UTF-8 感知：<code>u8_prev</code>/<code>u8_next</code>）</td></tr><tr><td>Home / Ctrl+A</td><td>0x84 / 0x01</td><td>行首</td></tr><tr><td>End / Ctrl+E</td><td>0x85 / 0x05</td><td>行尾</td></tr><tr><td>Delete</td><td>0x89</td><td>删除光标处字形</td></tr><tr><td>Backspace</td><td>0x08 / 0x7F</td><td>删除光标前字形</td></tr><tr><td>Ctrl+U</td><td>0x15</td><td>删除至行首</td></tr><tr><td>Ctrl+K</td><td>0x0B</td><td>删除至行尾</td></tr><tr><td>Ctrl+W</td><td>0x17</td><td>删除前一个词</td></tr><tr><td>Ctrl+C</td><td>0x03</td><td><code>^C</code> — 取消该行</td></tr><tr><td>Tab</td><td>0x09</td><td>补全（见下文）</td></tr><tr><td>0x100..0x1FF</td><td>—</td><td>串口粘贴的 UTF-8 字节：COM1 桥的 +0x100 偏置被剥离，因此粘贴的 CJK 逐字节累积</td></tr><tr><td>可打印 ASCII</td><td>—</td><td>在光标处插入</td></tr></tbody></table><p><strong>历史</strong>：16 条，每条 256 字节，连续重复去重， 满时 FIFO 滑动。<code>history</code> 打印带编号的列表。</p><h2 id="tab-补全-—-由注册表驱动" tabindex="-1">Tab 补全 — 由注册表驱动 <a class="header-anchor" href="#tab-补全-—-由注册表驱动" aria-label="Permalink to &quot;Tab 补全 — 由注册表驱动&quot;">​</a></h2><p>候选集是<strong>活动注册表</strong> —— <code>help</code> 打印的确切文本，经 L1SVC <code>l1/apps</code> op 获取（跳过页脚 <code>--</code> 行，上限 290 条）—— 加上 12 个真正的内建。</p><ul><li>单一匹配：补全该词并追加一个空格。</li><li>多重匹配：补全公共前缀。</li><li>无命令匹配且该词包含 <code>/</code>（或是行中靠后的任意词）： <strong>VFS 文件名补全</strong>启动 —— 目录部分经 sys_readdir 读取（扫描 64 条目，公共前缀逻辑， 有界追加）。</li></ul><p>补全从不枚举命令<em>参数</em> —— 子命令语法记录于 <a href="./function-dictionary.html">function-dictionary.md</a>。</p><h2 id="管道、重定向、后台" tabindex="-1">管道、重定向、后台 <a class="header-anchor" href="#管道、重定向、后台" aria-label="Permalink to &quot;管道、重定向、后台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>语法</th><th>限制</th></tr></thead><tbody><tr><td>管线</td><td><code>cmd1 | cmd2 | ...</code></td><td>最多 <strong>8 段</strong>；管道预先创建，每段一次 fork；第一个子进程保留控制台 stdin，最后一个保留控制台 stdout</td></tr><tr><td>重定向出</td><td><code>cmd &gt; file</code>（截断）、<code>cmd &gt;&gt; file</code>（追加）</td><td>可在命令任意位置解析；原 fd 被 dup() 并恢复；内建命令也能看到重定向</td></tr><tr><td>重定向入</td><td><code>cmd &lt; file</code></td><td>同一机制作用于 fd 0</td></tr><tr><td>后台</td><td><code>cmd &amp;</code></td><td>fork 不等待；作业表条目；打印 <code>[n] &lt;pid&gt;</code></td></tr></tbody></table><p>空重定向目标是语法错误：<code>ush: syntax error near &#39;&gt;&#39; </code>（以及 <code>near &#39;&lt;&#39;</code>）。</p><h2 id="变量替换-—-以及-ush-没有的东西" tabindex="-1">变量替换 — 以及 ush 没有的东西 <a class="header-anchor" href="#变量替换-—-以及-ush-没有的东西" aria-label="Permalink to &quot;变量替换 — 以及 ush 没有的东西&quot;">​</a></h2><p><code>$VAR</code> 展开是<strong>唯一</strong>的替换（<code>expand_env</code>，512 字节 结果；<code>echo $PATH</code>、<code>export X=...; run echo $X</code> 均可）。</p><p>该 shell 刻意<strong>不</strong>实现：</p><ul><li><strong>通配符/globbing</strong> — <code>ls *</code> 把字面 <code>*</code> 传给 <code>ls</code>，而 <code>ls</code> 同样没有 glob。任何地方都没有 <code>?</code>、没有 <code>[...]</code>。</li><li><code>&amp;&amp;</code> / <code>||</code> 链接</li><li><code>$?</code> 与任何其他特殊变量</li><li>引号（没有 <code>&#39;...&#39;</code> / <code>&quot;...&quot;</code>）</li><li>heredoc</li><li>函数、算术、循环 —— 脚本化就是每行一条命令</li></ul><p>命令未找到打印 <code>ush: command not found: &lt;cmd&gt;</code>；fork 失败 打印 <code>ush: fork failed</code>；别名展开溢出打印 <code>ush: alias expansion too long</code>。</p><hr><h2 id="编辑器" tabindex="-1">编辑器 <a class="header-anchor" href="#编辑器" aria-label="Permalink to &quot;编辑器&quot;">​</a></h2><p>一个共享引擎（<code>ocos/interface/l1_editor_core.h</code>），三张面孔： <strong>nano</strong> 与 <strong>edit</strong> 是逐字节相同的 nano 风格面孔（edit 是 v2.2.0 拼写）；<strong>vi</strong> 是同一引擎之上的真实模态层。 限制：256 行 × 每行 128 字节；超出限制的文件 部分加载（<code>unano_file_truncated</code> / <code>partial load</code>）且<strong>保存 拒绝覆盖</strong> —— 状态栏显示 <code>[PARTIAL: save refused]</code>。</p><h3 id="nano-edit-按键" tabindex="-1">nano / edit 按键 <a class="header-anchor" href="#nano-edit-按键" aria-label="Permalink to &quot;nano / edit 按键&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>动作</th></tr></thead><tbody><tr><td>方向键</td><td>按字形移动</td></tr><tr><td>键入</td><td>插入 UTF-8</td></tr><tr><td>Backspace / Delete</td><td>删除整个字形</td></tr><tr><td>ENTER</td><td>拆分该行</td></tr><tr><td><strong>F2</strong></td><td>切换<strong>系统 IME</strong>（拼音；引擎位于 L0 显示服务 —— 编辑器只负责切换 + 送键 + 渲染预编辑条）。组词中：数字 1-9 选择候选，空格 = 第一个，PgUp/PgDn 或 <code>-</code>/<code>=</code> 翻页，Backspace 退一字，Enter 提交原始字母，Esc 取消</td></tr><tr><td>Ctrl+K (0x0B)</td><td>剪切行</td></tr><tr><td>Ctrl+R (0x12)</td><td>复制行</td></tr><tr><td>Ctrl+U (0x15)</td><td>在下方粘贴剪贴板行（UTF-8 安全，单行剪贴板）</td></tr><tr><td>Ctrl+C (0x03)</td><td>报告光标位置</td></tr><tr><td>Ctrl+O (0x0F)</td><td>保存</td></tr><tr><td>Ctrl+X (0x18)</td><td>退出（有改动时询问）</td></tr><tr><td>Ctrl+G</td><td>帮助</td></tr></tbody></table><p>状态栏是差分式固定底行（ANSI <code>\\033[s\\033[999;1H\\033[K...\\033[u</code>；未变化时零输出）： <code>[* ]file 1/3 IME:on [preedit]</code>。</p><h3 id="vi-按键" tabindex="-1">vi 按键 <a class="header-anchor" href="#vi-按键" aria-label="Permalink to &quot;vi 按键&quot;">​</a></h3><p>COMMAND 模式（默认）：</p><table tabindex="0"><thead><tr><th>键</th><th>动作</th></tr></thead><tbody><tr><td><code>h j k l</code> / 方向键</td><td>移动（h/l 按字形）</td></tr><tr><td><code>0</code> / <code>$</code></td><td>行首 / 行尾</td></tr><tr><td><code>x</code></td><td>删除光标处字形</td></tr><tr><td><code>dd</code></td><td>剪切行</td></tr><tr><td><code>yy</code></td><td>复制行</td></tr><tr><td><code>p</code></td><td>在下方粘贴</td></tr><tr><td><code>i</code> / <code>a</code> / <code>o</code></td><td>进入 INSERT（在光标处 / 其后 / 下方新行）</td></tr><tr><td><code>:</code></td><td>ex 行：<code>:w</code> 保存，<code>:q</code> 退出，<code>:wq</code> 两者，<code>:q!</code> 丢弃</td></tr></tbody></table><p>INSERT 模式：键入即插入（UTF-8 字形感知），Backspace/Delete 删除整个字形，<strong>F2 切换系统 IME</strong>（与 nano 同一引擎），<code>Esc</code> 返回 COMMAND。状态栏：<code>[* ]file 1/3 CMD|INSERT</code></p><ul><li>预编辑条。</li></ul><hr><h2 id="tui-家族及其热键" tabindex="-1">TUI 家族及其热键 <a class="header-anchor" href="#tui-家族及其热键" aria-label="Permalink to &quot;TUI 家族及其热键&quot;">​</a></h2><p><code>tui</code>（桌面）与七个页面应用（<code>tui-sys</code>、<code>tui-sysinfo</code>、 <code>tui-hw</code>、<code>tui-drv</code>、<code>tui-net</code>、<code>tui-time</code>、<code>tui-ext</code>）全屏 渲染并绕过文本捕获（它们的输出从不进入 L1SVC 捕获缓冲）。<code>tui-test</code> 经 捕获提交其判定。所有页面共享一个按键循环：</p><table tabindex="0"><thead><tr><th>键</th><th>动作</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>下一页（标签栏显示 <code>[current]</code>）</td></tr><tr><td><code>Up</code> / <code>Down</code></td><td>滚动页面（长页如 PCI caps 可读到首屏之后）</td></tr><tr><td><code>+</code> / <code>=</code></td><td>音量 +10（Sound 页；将 <code>snd.volume</code> 持久化到 config）</td></tr><tr><td><code>-</code></td><td>音量 -10</td></tr><tr><td><code>F1</code></td><td>帮助（共享的 sysinfo 帮助屏）</td></tr><tr><td><code>F2</code></td><td>保存配置（<code>/etc/opencube.conf</code> 或默认值）</td></tr><tr><td><code>F5</code></td><td>重绘</td></tr><tr><td><code>Esc</code> / <code>F10</code> / <code>q</code></td><td>离开页面，回到提示符</td></tr></tbody></table><h2 id="配方" tabindex="-1">配方 <a class="header-anchor" href="#配方" aria-label="Permalink to &quot;配方&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; help -w                          # find commands by group</span></span>
<span class="line"><span>ush&gt; top -n 5                         # five refreshes, then exits</span></span>
<span class="line"><span>ush&gt; cat /etc/opencube.conf           # no pager; pipe into head</span></span>
<span class="line"><span>ush&gt; dmesg 100 &gt; /tmp/boot.txt        # capture the last 100 klog lines</span></span>
<span class="line"><span>ush&gt; grep dhcp &lt; /tmp/boot.txt        # grep filters stdin</span></span>
<span class="line"><span>ush&gt; play 440 &amp;                       # background job: [1] 12</span></span>
<span class="line"><span>ush&gt; jobs                             # see it</span></span>
<span class="line"><span>ush&gt; ime -i                           # interactive pinyin compose line</span></span></code></pre></div><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./function-dictionary.html">function-dictionary.md</a> — 全部 311 条命令</li><li><a href="./shell-basics.html">shell-basics.md</a> — 新手导览</li><li><a href="./getting-started.html">getting-started.md</a> — 首次启动</li><li><a href="./../troubleshooting/silent-failures.html">../troubleshooting/silent-failures.md</a> — 为何某些控制台输出从不出现（捕获路由）</li></ul>`,42)])])}const g=d(a,[["render",r]]);export{u as __pageData,g as default};
